    String? xSite,
    required models.SimilarAppearanceQuery body,
  }) async {
    final _options = (options ?? Options()).copyWith(
      method: "POST",
      responseType: ResponseType.json,
      extra: {...?options?.extra, ...extra},
      contentType: "application/json",
      headers: {
        for (final entry in (options?.headers ?? const <String, Object?>{}).entries)
          if (entry.key.toLowerCase() != 'content-type') entry.key: entry.value,
        'Accept': "application/json",
        if (xSite != null) "X-Site": xSite,
      },
      validateStatus: (status) => status != null && (status == 200),
    );
    final response = await _transport.request<dynamic>(
      "/api/v1/analytics/appearances/similar",
      options: _options,
      data: convert.jsonEncode(body),
      cancelToken: cancelToken,
    );
    return models.SimilarAppearances.fromJson(response.data as Map<String, Object?>);
  }
}
